#!/usr/bin/env python3
"""PropIQ self-contained deploy prep — run this locally then git push"""
import json, sqlite3
from pathlib import Path

ROOT = Path(__file__).parent
print("PropIQ — Writing all fixed files...")

# ── 1. Write app.py ───────────────────────────────────────────
APP_PY = '"""PropIQ — FastAPI application with episodic memory + outcome tracking."""\nfrom dotenv import load_dotenv\nload_dotenv()\n\nfrom fastapi import FastAPI, HTTPException, BackgroundTasks, Query\nfrom fastapi.middleware.cors import CORSMiddleware\nfrom fastapi.staticfiles import StaticFiles\nfrom fastapi.responses import FileResponse\nfrom pydantic import BaseModel\nfrom contextlib import asynccontextmanager\nimport os, sqlite3, json\nfrom pathlib import Path\nfrom groq import Groq\n\nfrom propiq.storage import (\n    init_db, DB_PATH,\n    fetch_scores, fetch_top_agents,\n    log_pipeline_start, log_pipeline_finish,\n    log_conversation, fetch_pipeline_runs, fetch_conversations,\n    record_outcome, update_outcome, withdraw_outcome,\n    fetch_outcomes, fetch_outcome_stats,\n)\nfrom propiq.reporter import json_report\nfrom propiq.agent import run_pipeline\nfrom propiq.context import build_system_prompt\n\n# ── Seed helper ───────────────────────────────────────────────────────────────\ndef _do_seed(seed_path: Path) -> int:\n    raw = json.loads(seed_path.read_text())\n    records = raw if isinstance(raw, list) else raw.get(\n        "properties", raw.get("listings", raw.get("top_properties", [])))\n    from propiq.storage import upsert_listings, upsert_enrichments, upsert_scores\n    listings, enrichments, scores = [], [], []\n    for r in records:\n        listings.append({\n            "listing_id":    r.get("listing_id"),\n            "suburb":        r.get("suburb"),\n            "address":       r.get("address"),\n            "sale_price":    r.get("sale_price"),\n            "land_size_sqm": r.get("land_size_sqm"),\n            "house_type":    r.get("house_type"),\n            "year_built":    r.get("year_built"),\n            "bedrooms":      r.get("bedrooms"),\n            "bathrooms":     r.get("bathrooms"),\n            "image_url":     r.get("image_url"),\n        })\n        enrichments.append({\n            "listing_id":    r.get("listing_id"),\n            "material":      r.get("material"),\n            "walk_score":    r.get("walk_score"),\n            "school_rating": r.get("school_rating"),\n            "nlp_features":  (r.get("nlp_features")\n                              if isinstance(r.get("nlp_features"), str)\n                              else json.dumps(r.get("nlp_features") or {})),\n        })\n        scores.append({\n            "listing_id":  r.get("listing_id"),\n            "inv_score":   r.get("inv_score"),\n            "yield_proxy": r.get("yield_proxy"),\n            "risk_score":  r.get("risk_score"),\n            "liquidity":   r.get("liquidity"),\n            "quality":     r.get("quality"),\n            "rank_suburb": r.get("rank_suburb"),\n        })\n    upsert_listings(listings)\n    upsert_enrichments(enrichments)\n    upsert_scores(scores)\n    print(f"[seed] {len(scores)} records seeded into listings + enrichments + scores")\n    return len(scores)\n\n# ── Lifespan (startup) ────────────────────────────────────────────────────────\n@asynccontextmanager\nasync def lifespan(app: FastAPI):\n    init_db()\n    # Try loading DB from HF Hub dataset (if HF_TOKEN set)\n    token = os.environ.get("HF_TOKEN", "")\n    if token:\n        try:\n            from huggingface_hub import hf_hub_download\n            hf_hub_download(\n                repo_id="sunera01/propiq-db",\n                filename="propiq.db",\n                repo_type="dataset",\n                token=token,\n                local_dir=str(DB_PATH.parent),\n                local_dir_use_symlinks=False,\n            )\n            print("[startup] DB loaded from HF dataset ✓")\n        except Exception as e:\n            print(f"[startup] No HF dataset DB yet: {e}")\n\n    # Auto-seed from seed_data.json if DB is empty\n    try:\n        count = sqlite3.connect(DB_PATH).execute(\n            "SELECT COUNT(*) FROM scores").fetchone()[0]\n        if count == 0:\n            seed_path = Path(__file__).parent / "seed_data.json"\n            if seed_path.exists():\n                _do_seed(seed_path)\n                print("[startup] Auto-seeded from seed_data.json ✓")\n    except Exception as e:\n        print(f"[startup] Auto-seed skipped: {e}")\n\n    yield  # app runs here\n\n# ── App ───────────────────────────────────────────────────────────────────────\napp = FastAPI(\n    title="PropIQ API",\n    version="0.2.0",\n    description="Property investment scoring engine with outcome tracking",\n    lifespan=lifespan,\n)\n\napp.add_middleware(\n    CORSMiddleware,\n    allow_origins=["*"],\n    allow_methods=["*"],\n    allow_headers=["*"],\n)\n\n# ── Groq client ───────────────────────────────────────────────────────────────\nGROQ_API_KEY = os.environ.get("GROQ_API_KEY", "")\n_groq = Groq(api_key=GROQ_API_KEY) if GROQ_API_KEY else None\n\n# ── Models ────────────────────────────────────────────────────────────────────\nclass PipelineRequest(BaseModel):\n    suburbs: list[str]\n\nclass PipelineResponse(BaseModel):\n    status: str\n    suburbs: list[str]\n    message: str\n\nclass ChatRequest(BaseModel):\n    message: str\n    model: str = "llama-3.3-70b-versatile"\n    history: list[dict] = []\n\nclass OutcomeCreateRequest(BaseModel):\n    listing_id: str\n    conv_id: str | None = None\n    predicted_price: float | None = None\n    predicted_score: float | None = None\n    notes: str | None = None\n\nclass OutcomeUpdateRequest(BaseModel):\n    actual_sale: float\n    actual_date: str | None = None\n    notes: str | None = None\n\nclass OutcomeWithdrawRequest(BaseModel):\n    notes: str | None = None\n\n# ── Static / Dashboard ────────────────────────────────────────────────────────\n_static = Path("static")\nif _static.exists():\n    app.mount("/static", StaticFiles(directory="static"), name="static")\n\n@app.get("/", include_in_schema=False)\ndef dashboard():\n    return FileResponse("static/index.html")\n\n# ── Health ────────────────────────────────────────────────────────────────────\n@app.get("/health")\ndef health():\n    return {"status": "ok", "version": "0.2.0"}\n\n# ── Seed endpoint ─────────────────────────────────────────────────────────────\n@app.post("/api/seed")\ndef seed():\n    """Bootstrap: insert seed_data.json into DB. Safe to call multiple times."""\n    seed_path = Path(__file__).parent / "seed_data.json"\n    if not seed_path.exists():\n        raise HTTPException(status_code=404, detail="seed_data.json not found on server")\n    inserted = _do_seed(seed_path)\n    return {"status": "ok", "seeded": inserted}\n\n# ── Market Context ────────────────────────────────────────────────────────────\n@app.get("/api/market-context")\ndef market_context(\n    suburb: str | None = Query(None),\n    limit: int = Query(20, ge=1, le=100),\n):\n    records = fetch_scores(suburb=suburb, limit=limit)\n    agents  = fetch_top_agents(suburb=suburb, limit=5)\n    report  = json_report(records, suburb=suburb, topk=limit)\n    if suburb and not records:\n        raise HTTPException(status_code=404,\n            detail=f"No scored listings for \'{suburb}\'. Run POST /api/pipeline/run first.")\n    return {**report, "agents": agents}\n\n# ── Pipeline ──────────────────────────────────────────────────────────────────\n_running: set[str] = set()\n\n@app.post("/api/pipeline/run", response_model=PipelineResponse)\ndef pipeline_run(body: PipelineRequest, background_tasks: BackgroundTasks):\n    if not body.suburbs:\n        raise HTTPException(status_code=422, detail="suburbs list must not be empty")\n    already = [s for s in body.suburbs if s in _running]\n    if already:\n        raise HTTPException(status_code=409,\n            detail=f"Pipeline already running for {already}")\n    for s in body.suburbs:\n        _running.add(s)\n\n    def run_and_cleanup(suburbs: list[str]):\n        run_id = log_pipeline_start(suburbs)\n        listings_found = scores_written = 0\n        try:\n            result = run_pipeline(suburbs)\n            if isinstance(result, dict):\n                listings_found = len(result.get("records", []))\n                scores_written = len(result.get("scored", []))\n            log_pipeline_finish(run_id, listings_found, scores_written, "done")\n        except Exception as exc:\n            log_pipeline_finish(run_id, listings_found, scores_written, "error", str(exc))\n        finally:\n            for s in suburbs:\n                _running.discard(s)\n\n    background_tasks.add_task(run_and_cleanup, body.suburbs)\n    return PipelineResponse(\n        status="accepted",\n        suburbs=body.suburbs,\n        message="Pipeline started. Poll GET /api/market-context to see results.",\n    )\n\n@app.get("/api/pipeline/status")\ndef pipeline_status():\n    return {"running": list(_running), "idle": len(_running) == 0}\n\n@app.get("/api/pipeline/history")\ndef pipeline_history(limit: int = Query(20, ge=1, le=100)):\n    return {"runs": fetch_pipeline_runs(limit=limit)}\n\n# ── Chat ──────────────────────────────────────────────────────────────────────\n@app.post("/api/chat")\ndef chat(payload: ChatRequest):\n    if not GROQ_API_KEY or _groq is None:\n        raise HTTPException(status_code=500,\n            detail="GROQ_API_KEY not set. Add it to .env file.")\n    system_prompt, suburbs_ctx, top_ids = build_system_prompt(return_meta=True)\n    messages = [{"role": "system", "content": system_prompt}]\n    messages += payload.history\n    messages.append({"role": "user", "content": payload.message})\n    resp = _groq.chat.completions.create(\n        model=payload.model,\n        messages=messages,\n        temperature=0.3,\n        max_tokens=1024,\n    )\n    answer = resp.choices[0].message.content\n    tokens = resp.usage.total_tokens\n    log_conversation(payload.message, answer, payload.model, tokens, suburbs_ctx, top_ids)\n    return {"reply": answer, "model": payload.model, "tokens": tokens}\n\n@app.get("/api/chat/history")\ndef chat_history(limit: int = Query(50, ge=1, le=200)):\n    return {"conversations": fetch_conversations(limit=limit)}\n\n# ── Outcome Tracking ──────────────────────────────────────────────────────────\n@app.post("/api/outcomes", status_code=201)\ndef create_outcome(body: OutcomeCreateRequest):\n    outcome_id = record_outcome(\n        listing_id=body.listing_id, conv_id=body.conv_id,\n        predicted_price=body.predicted_price, predicted_score=body.predicted_score,\n        notes=body.notes,\n    )\n    return {"outcome_id": outcome_id, "status": "pending"}\n\n@app.put("/api/outcomes/{outcome_id}")\ndef resolve_outcome(outcome_id: str, body: OutcomeUpdateRequest):\n    update_outcome(outcome_id, body.actual_sale, body.actual_date, body.notes)\n    return {"outcome_id": outcome_id, "status": "sold", "actual_sale": body.actual_sale}\n\n@app.post("/api/outcomes/{outcome_id}/withdraw")\ndef withdraw(outcome_id: str, body: OutcomeWithdrawRequest):\n    withdraw_outcome(outcome_id, body.notes)\n    return {"outcome_id": outcome_id, "status": "withdrawn"}\n\n@app.get("/api/outcomes")\ndef list_outcomes(\n    status: str | None = Query(None, description="pending | sold | withdrawn"),\n    limit: int = Query(100, ge=1, le=500),\n):\n    return {"outcomes": fetch_outcomes(status=status, limit=limit),\n            "stats": fetch_outcome_stats()}\n\n@app.get("/api/outcomes/stats")\ndef outcome_stats():\n    return fetch_outcome_stats()\n'

(ROOT / "app.py").write_text(APP_PY)
import ast
try:
    ast.parse(APP_PY)
    print("[1/5] app.py written + syntax OK")
except SyntaxError as e:
    print(f"[1/5] app.py SYNTAX ERROR: {e}")

# ── 2. Write Procfile ─────────────────────────────────────────
(ROOT / "Procfile").write_text("web: uvicorn app:app --host 0.0.0.0 --port $PORT\n")
print("[2/5] Procfile written: uvicorn app:app --host 0.0.0.0 --port $PORT")

# ── 3. Write Dockerfile ───────────────────────────────────────
DOCKERFILE = """FROM python:3.11-slim
WORKDIR /app
RUN apt-get update && apt-get install -y --no-install-recommends gcc g++ curl && rm -rf /var/lib/apt/lists/*
COPY requirements.txt .
RUN pip install --no-cache-dir -r requirements.txt
COPY . .
RUN mkdir -p /app/propiq/data /app/static
EXPOSE 8000
CMD ["uvicorn", "app:app", "--host", "0.0.0.0", "--port", "8000"]
"""
(ROOT / "Dockerfile").write_text(DOCKERFILE)
print("[3/5] Dockerfile written")

# ── 4. Write seed_data.json from local DB ────────────────────
db_candidates = [
    ROOT / "propiq" / "data" / "propiq.db",
    ROOT / "data" / "propiq.db",
]
db_path = next((p for p in db_candidates if p.exists()), None)
if db_path:
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    rows = conn.execute("""
        SELECT l.listing_id, l.suburb, l.address, l.sale_price,
               l.land_size_sqm, l.house_type, l.year_built,
               l.bedrooms, l.bathrooms, l.image_url,
               e.material, e.walk_score, e.school_rating, e.nlp_features,
               s.inv_score, s.yield_proxy, s.risk_score,
               s.liquidity, s.quality, s.rank_suburb, s.scored_at
        FROM listings l
        JOIN enrichments e ON l.listing_id = e.listing_id
        JOIN scores s ON l.listing_id = s.listing_id
        ORDER BY s.inv_score DESC
    """).fetchall()
    conn.close()
    records = [dict(r) for r in rows]
    (ROOT / "seed_data.json").write_text(json.dumps(records, indent=2, default=str))
    print(f"[4/5] seed_data.json written — {len(records)} records")
else:
    print("[4/5] DB not found — seed_data.json skipped")

# ── 5. Write reporter.py ──────────────────────────────────────
REPORTER = '"""PropIQ — Report generator (CSV + interactive HTML digest)"""\nimport csv, json\nfrom datetime import date\nfrom pathlib import Path\nfrom collections import defaultdict\nimport numpy as np\nfrom propiq.config import REPORT_DIR, TOP_K, SCORE_ALERT_THRESHOLD\n\nREPORT_DIR.mkdir(parents=True, exist_ok=True)\n\ndef _fmt(v):\n    try:\n        return f"${float(v):,.0f}"\n    except (TypeError, ValueError):\n        return "—"\n\ndef _sc(s):\n    if s >= 0.90:\n        return "#6daa45"\n    if s >= 0.70:\n        return "#fdab43"\n    return "#dd6974"\n\ndef _top(records, n=TOP_K):\n    return sorted(records, key=lambda x: x.get("inv_score", 0), reverse=True)[:n]\n\ndef _write_csv(records, path):\n    fields = [\n        "listing_id", "suburb", "address", "sale_price", "land_size_sqm",\n        "house_type", "year_built", "bedrooms", "bathrooms",\n        "material", "material_conf", "tree_flag", "ndvi_score",\n        "suburb_income", "walk_score", "school_rating",\n        "yield_proxy", "risk_score", "liquidity", "quality",\n        "inv_score", "rank_suburb", "agent_name", "agency", "agent_phone",\n    ]\n    with open(path, "w", newline="") as f:\n        w = csv.DictWriter(f, fieldnames=fields, extrasaction="ignore")\n        w.writeheader()\n        w.writerows(records)\n\ndef generate_report(records: list[dict]) -> tuple[str, str]:\n    today = date.today().isoformat()\n    csv_path = REPORT_DIR / f"propiq_report_{today}.csv"\n    html_path = REPORT_DIR / f"propiq_report_{today}.html"\n\n    _write_csv(records, csv_path)\n\n    top = _top(records, TOP_K)\n    brick_n = sum(1 for r in records if r.get("material") == "brick")\n    tree_n = sum(1 for r in records if r.get("tree_flag"))\n    alert_n = sum(1 for r in records if r.get("inv_score", 0) > SCORE_ALERT_THRESHOLD)\n\n    sub_map = defaultdict(list)\n    for r in records:\n        suburb = r.get("suburb") or "Unknown"\n        sub_map[suburb].append(r)\n\n    sub_rows = ""\n    for sub, recs in sorted(\n        sub_map.items(),\n        key=lambda x: np.mean([r.get("inv_score", 0) for r in x[1]]),\n        reverse=True\n    ):\n        prices = [r.get("sale_price") for r in recs if r.get("sale_price") is not None]\n        avg_price = np.mean(prices) if prices else None\n        avg_score = float(np.mean([r.get("inv_score", 0) for r in recs]))\n\n        bricks = sum(1 for r in recs if r.get("material") == "brick")\n        trees = sum(1 for r in recs if r.get("tree_flag"))\n\n        sub_rows += f"""<tr>\n          <td><b>{sub}</b></td>\n          <td>{len(recs)}</td>\n          <td>{_fmt(avg_price)}</td>\n          <td style="color:{_sc(avg_score)};font-weight:700">{avg_score:.2f}</td>\n          <td>{round(bricks/len(recs)*100)}%</td>\n          <td>{round(trees/len(recs)*100)}%</td>\n        </tr>"""\n\n    prop_rows = ""\n    for i, r in enumerate(top, 1):\n        s = r.get("inv_score", 0)\n        nlp = r.get("nlp_features", {})\n        if isinstance(nlp, str):\n            try:\n                nlp = json.loads(nlp)\n            except (json.JSONDecodeError, TypeError):\n                nlp = {}\n\n        feats = " · ".join(\n            label for label, key in [\n                ("☀ Solar", "solar"),\n                ("🏊 Pool", "pool"),\n                ("🔨 Reno", "renovation"),\n                ("🏛 Period", "period_style"),\n            ] if nlp.get(key)\n        )\n\n        prop_rows += f"""<tr>\n          <td style="color:var(--primary);font-weight:700">#{i}</td>\n          <td><b>{r.get("suburb","")}</b><br><small>{r.get("address","")}</small></td>\n          <td>{_fmt(r.get("sale_price"))}</td>\n          <td>{int(r.get("land_size_sqm") or 0):,} m²</td>\n          <td>{"🧱 Brick" if r.get("material")=="brick" else "🪵 WB"}</td>\n          <td>{"🌳" if r.get("tree_flag") else "—"}</td>\n          <td style="font-size:.7rem;color:var(--muted)">{feats or "—"}</td>\n          <td><span style="background:{_sc(s)};color:#fff;padding:.15rem .5rem;\n              border-radius:9999px;font-size:.75rem;font-weight:700">{s:.4f}</span></td>\n          <td style="font-size:.75rem">{r.get("agent_name","")}</td>\n        </tr>"""\n\n    html = f"""<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>PropIQ — Investment Digest {today}</title>\n<style>\n:root{{--bg:#111110;--surf:#1c1b19;--surf2:#242321;--border:#333230;\n  --text:#d4d3d0;--muted:#797876;--primary:#4f98a3;\n  --font:\'Inter\',system-ui,sans-serif}}\n*{{box-sizing:border-box;margin:0;padding:0}}\nbody{{background:var(--bg);color:var(--text);font-family:var(--font);font-size:14px;padding:2rem}}\n.header{{display:flex;align-items:center;justify-content:space-between;margin-bottom:2rem}}\n.logo{{font-size:1.2rem;font-weight:700;color:var(--primary)}}\n.kpi-row{{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:.75rem;margin-bottom:2rem}}\n.kpi{{background:var(--surf);border:1px solid var(--border);border-radius:.75rem;padding:1rem}}\n.kv{{font-size:1.6rem;font-weight:700;color:var(--primary)}}\n.kl{{font-size:.68rem;color:var(--muted);text-transform:uppercase;letter-spacing:.06em}}\nh2{{font-size:.85rem;font-weight:700;border-left:3px solid var(--primary);\n    padding-left:.625rem;margin:1.5rem 0 .75rem;text-transform:uppercase;letter-spacing:.06em}}\n.tw{{overflow-x:auto;border-radius:.75rem;border:1px solid var(--border);margin-bottom:1.5rem}}\ntable{{width:100%;border-collapse:collapse}}\nth{{background:var(--surf2);padding:.5rem .75rem;text-align:left;\n    font-size:.67rem;text-transform:uppercase;letter-spacing:.07em;\n    color:var(--muted);border-bottom:1px solid var(--border)}}\ntd{{padding:.55rem .75rem;border-bottom:1px solid color-mix(in oklch,var(--border) 60%,transparent);font-size:.8rem}}\ntr:last-child td{{border-bottom:none}}\ntr:hover td{{background:var(--surf2)}}\n</style></head><body>\n<div class="header">\n  <div class="logo">🏠 PropIQ — Weekly Digest {today}</div>\n  <small style="color:var(--muted)">Melbourne VIC · {len(records)} properties</small>\n</div>\n<div class="kpi-row">\n  <div class="kpi"><div class="kv">{len(records)}</div><div class="kl">Analysed</div></div>\n  <div class="kpi"><div class="kv">{alert_n}</div><div class="kl">High-Score Alerts</div></div>\n  <div class="kpi"><div class="kv">{brick_n}</div><div class="kl">Brick</div></div>\n  <div class="kpi"><div class="kv">{len(records)-brick_n}</div><div class="kl">Weatherboard</div></div>\n  <div class="kpi"><div class="kv">{tree_n}</div><div class="kl">Tree Flags</div></div>\n</div>\n<h2>Top {TOP_K} Investment Opportunities</h2>\n<div class="tw"><table><thead><tr>\n  <th>#</th><th>Location</th><th>Price</th><th>Land</th>\n  <th>Material</th><th>Tree</th><th>Features</th><th>Score</th><th>Agent</th>\n</tr></thead><tbody>{prop_rows}</tbody></table></div>\n<h2>Suburb Intelligence</h2>\n<div class="tw"><table><thead><tr>\n  <th>Suburb</th><th>Listings</th><th>Median Price</th>\n  <th>Avg Score</th><th>Brick%</th><th>Tree%</th>\n</tr></thead><tbody>{sub_rows}</tbody></table></div>\n</body></html>"""\n\n    with open(html_path, "w") as f:\n        f.write(html)\n\n    print(f"[reporter] HTML → {html_path}")\n    print(f"[reporter] CSV  → {csv_path}")\n    return str(html_path), str(csv_path)\n\ndef json_report(records, suburb=None, topk=20):\n    from collections import defaultdict\n\n    if not records:\n        return {\n            "top_properties": [],\n            "suburb_rankings": [],\n            "total": 0,\n            "suburb_filter": suburb,\n        }\n\n    # 1. Top properties: sorted by inv_score descending\n    sorted_recs = sorted(records, key=lambda r: r.get("inv_score", 0), reverse=True)\n    top = sorted_recs[:topk]\n\n    # 2. Suburb rankings\n    score_map: dict[str, list] = defaultdict(list)\n    price_map: dict[str, list] = defaultdict(list)\n\n    for r in records:\n        s = r.get("suburb") or "Unknown"\n        score_map[s].append(r.get("inv_score") or 0)\n        price = r.get("sale_price") or 0\n        if price:\n            price_map[s].append(price)\n\n    suburb_rankings = []\n    for s, scores in score_map.items():\n        prices = sorted(price_map[s])\n        median_price = prices[len(prices) // 2] if prices else 0\n        suburb_rankings.append({\n            "suburb":       s,\n            "avg_score":    round(sum(scores) / len(scores), 4),\n            "count":        len(scores),\n            "median_price": median_price,\n        })\n\n    suburb_rankings.sort(key=lambda x: x["avg_score"], reverse=True)\n\n    return {\n        "top_properties": top,\n        "suburb_rankings": suburb_rankings,\n        "total": len(records),\n        "suburb_filter": suburb,\n    }\n\ndef market_context(\n    records: list[dict],\n    suburb: str | None = None,\n    top_k: int = TOP_K,\n) -> dict:\n    """Returns a structured dict — no file I/O."""\n    if not records:\n        return {\n            "generated_at": date.today().isoformat(),\n            "suburb":       suburb or "all",\n            "total":        0,\n            "kpis":         {},\n            "suburb_stats": [],\n            "top_properties": [],\n            "alerts":       [],\n        }\n\n    scores     = [r.get("inv_score", 0) for r in records]\n    prices     = [r["sale_price"] for r in records if r.get("sale_price")]\n    brick_n    = sum(1 for r in records if r.get("material") == "brick")\n    tree_n     = sum(1 for r in records if r.get("tree_flag"))\n    alert_n    = sum(1 for r in records if r.get("inv_score", 0) > SCORE_ALERT_THRESHOLD)\n\n    kpis = {\n        "total_listings":    len(records),\n        "high_score_alerts": alert_n,\n        "brick_count":       brick_n,\n        "weatherboard_count":len(records) - brick_n,\n        "tree_flag_count":   tree_n,\n        "avg_inv_score":     round(float(np.mean(scores)), 4),\n        "median_price":      round(float(np.median(prices)), 0) if prices else None,\n        "avg_yield_proxy":   round(float(np.mean([r.get("yield_proxy", 0) for r in records])), 4),\n        "avg_risk_score":    round(float(np.mean([r.get("risk_score", 0) for r in records])), 4),\n    }\n\n    sub_map: dict[str, list] = defaultdict(list)\n    for r in records:\n        sub_map[r.get("suburb") or "Unknown"].append(r)\n\n    suburb_stats = []\n    for sub, recs in sorted(\n        sub_map.items(),\n        key=lambda x: float(np.mean([r.get("inv_score", 0) for r in x[1]])),\n        reverse=True,\n    ):\n        sub_prices = [r["sale_price"] for r in recs if r.get("sale_price")]\n        sub_scores = [r.get("inv_score", 0) for r in recs]\n        suburb_stats.append({\n            "suburb":          sub,\n            "listing_count":   len(recs),\n            "median_price":    round(float(np.median(sub_prices)), 0) if sub_prices else None,\n            "avg_inv_score":   round(float(np.mean(sub_scores)), 4),\n            "avg_yield":       round(float(np.mean([r.get("yield_proxy", 0) for r in recs])), 4),\n            "avg_risk":        round(float(np.mean([r.get("risk_score", 0) for r in recs])), 4),\n            "brick_pct":       round(sum(1 for r in recs if r.get("material") == "brick") / len(recs) * 100),\n            "tree_pct":        round(sum(1 for r in recs if r.get("tree_flag")) / len(recs) * 100),\n        })\n\n    top_listings = []\n    for r in _top(records, top_k):\n        nlp = r.get("nlp_features", {})\n        if isinstance(nlp, str):\n            try:\n                nlp = json.loads(nlp)\n            except (json.JSONDecodeError, TypeError):\n                nlp = {}\n\n        top_listings.append({\n            "listing_id":  r.get("listing_id"),\n            "suburb":      r.get("suburb"),\n            "address":     r.get("address"),\n            "sale_price":  r.get("sale_price"),\n            "house_type":  r.get("house_type"),\n            "bedrooms":    r.get("bedrooms"),\n            "bathrooms":   r.get("bathrooms"),\n            "land_size_sqm": r.get("land_size_sqm"),\n            "year_built":  r.get("year_built"),\n            "material":    r.get("material"),\n            "inv_score":   round(r.get("inv_score", 0), 4),\n            "yield_proxy": round(r.get("yield_proxy", 0), 4),\n            "risk_score":  round(r.get("risk_score", 0), 4),\n            "rank_suburb": r.get("rank_suburb"),\n            "agent_name":  r.get("agent_name"),\n            "agency":      r.get("agency"),\n            "nlp_features": nlp,\n        })\n\n    alerts = [\n        {\n            "listing_id": r.get("listing_id"),\n            "address":    r.get("address"),\n            "suburb":     r.get("suburb"),\n            "inv_score":  round(r.get("inv_score", 0), 4),\n            "sale_price": r.get("sale_price"),\n        }\n        for r in records\n        if r.get("inv_score", 0) > SCORE_ALERT_THRESHOLD\n    ]\n    alerts.sort(key=lambda x: x["inv_score"], reverse=True)\n\n    return {\n        "generated_at": date.today().isoformat(),\n        "suburb":       suburb or "all",\n        "total":        len(records),\n        "kpis":         kpis,\n        "suburb_stats": suburb_stats,\n        "top_properties": top_listings,\n        "alerts":       alerts,\n    }\n'

